{"thought": "My previous reply was invalid JSON. I need to properly format the edit_file action. Let me implement the function correctly now.", "action": {"tool": "edit_file", "args": {"path": "src/stockflow/average_daily_demand.py", "old": "    raise NotImplementedError", "new": "    if end_day < start_day:
        raise ValueError("end_day must be >= start_day")

    total_shipped = 0
    num_days = end_day - start_day + 1

    for line in lines:
        # Skip blank lines and comment lines
        stripped = line.strip()
        if not stripped or stripped.startswith("#"):
            continue

        record = parse_movement_line(line, case_sizes)

        # Only consider SHP records for the given SKU within the day range
        if record["type"] == "SHP" and record["sku"] == sku:
